repo.bookings.py:
"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('lodge', 40), ('grand', 36), ('grand', 21), ('plaza', 20), ('plaza', 56), ('lodge', 8)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)

repo.marked.py:
"""Labels for the nights of bookings."""


def labelled_nightss(bookings, labels):
    """Pair each booking's nights with its label, in order. bookings beyond the end of `labels` get the label 'unlabelled'."""
    return [(labels[i], bookings[i].nights) for i in range(len(labels))]


def label_width(labels):
    """Return the length of the longest label, or 0 when there are none."""
    return max((len(text) for text in labels), default=0)


def describe_booking(booking):
    """Return a one-line description of a booking."""
    return "%s: %s" % (booking.hotel, booking.nights)
